for a in answers:
    referrer = a['code_id'] + '|' + a['source_id']
    checks = []
    for key in references['requirements'][referrer]:
        target = references['targets'][key]
        number = target['number']
        if number in common_rules:
            assessment = contexts[a['number']] + ' ' + common_rules[number]
        else:
            assessment = specific_checks[(a['number'], number)]
        checks.append(dict(target_key=key, view_sha256=target['view_sha256'],
                           assessment=assessment))
    a['reference_checks'] = checks

Path('answer.json').write_text(json.dumps(answers, ensure_ascii=False, indent=2) + '\n')
print(f'answer.json : {len(answers)} articles')
